const { chromium } = require('playwright');
const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');
const port = 39838;
const server = spawn(process.execPath, ['server.js'], { cwd: '/var/tmp/avb-runs/avb-0HXlqN/project', env: { ...process.env, PORT: String(port) }, stdio: 'ignore' });
function wait(){return new Promise((res,rej)=>{let n=0;const tick=()=>http.get({host:'127.0.0.1',port,path:'/'},r=>{r.resume();res();}).on('error',()=>{if(++n>100)rej(new Error('timeout'));else setTimeout(tick,50);});tick();});}
(async()=>{
  await wait();
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  await page.goto(`http://127.0.0.1:${port}/about.html`);
  const data = await page.evaluate(() => {
    const out = [];
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      const t = node.textContent;
      if (!t.trim()) continue;
      const el = node.parentElement;
      const cs = getComputedStyle(el);
      for (let i = 0; i < t.length; i++) {
        if (!t[i].trim()) continue;
        const r = document.createRange();
        r.setStart(node, i); r.setEnd(node, i + 1);
        const rect = r.getBoundingClientRect();
        if (rect.width === 0) continue;
        out.push({ ch: t[i], x: rect.x, y: rect.y, w: rect.width, h: rect.height,
                   fs: cs.fontSize, fw: cs.fontWeight, color: cs.color });
      }
    }
    return out;
  });
  fs.writeFileSync(process.env.TMPDIR + '/chars.json', JSON.stringify(data));
  await page.screenshot({ path: process.env.TMPDIR + '/cand/about-now.png', fullPage: true });
  console.log('chars', data.length);
  await browser.close(); server.kill();
})().catch(e=>{console.error(e);server.kill();process.exit(1);});
